function directURL(host,path){const u=new URL('http://'+host+'/api/file');u.searchParams.set('path',REMOTE_ROOT+'/'+path);u.searchParams.set('download','1');return u.href;}
function alternatePath(path){return path.startsWith('改革宗心灵辅导资料/')?path.slice('改革宗心灵辅导资料/'.length):'改革宗心灵辅导资料/'+path;}
function renderBookDetail(id){const b=byId.get(id);if(!b)return;state.route='library';state.book=id;writeResearchAddress(false);const links=[];for(const [label,host] of [['主线路','103.143.81.181'],['备用线路','85.189.89.208']]){for(const [pathLabel,p] of [['完整目录层级',b.source_path],['简化目录层级',alternatePath(b.source_path)]])links.push(`<a class="btn" target="_blank" rel="noopener noreferrer" href="${esc(directURL(host,p))}">${esc(label+' · '+pathLabel)}（原文件）</a>`);}
container(`<section class="panel"> <button class="btn" data-route="library">返回书目检索</button><div class="line"></div><p class="eyebrow">来源保全 · 不是内容审批</p><h1>${esc(b.original_title)}</h1><span class="pill amber">未完成专业审读</span><span class="pill amber">公开许可待核</span>${b.id==='256'?'<div class="warn-box"><strong>已发现需人工修订的重大内容（第十一轮）</strong><p>本篇全文已有来源校验，涉及救恩身份、认罪边界、正当申辩、经文误字等未决审读问题。原文暂不可直接作为针对个人的自动辅导结论。</p><button class="btn" data-lie-bookreview>进入第256号审查页</button></div>':''}${b.identical_source_ids.length?`<span class="pill">内容重复别名 ${b.identical_source_ids.length} 条</span>`:''}<table class="smalltable"><tr><th>原始位置</th><td style="overflow-wrap:anywhere">${esc(b.source_path)}</td></tr><tr><th>文件大小</th><td>${fmt(b.bytes)} 字节</td></tr><tr><th>SHA-256</th><td style="overflow-wrap:anywhere">${esc(b.source_sha256)}</td></tr><tr><th>研究主类</th><td>${esc(b.research_topic_name)}（第二轮候选）</td></tr><tr><th>处境标签</th><td>${b.situations.length?b.situations.map(k=>esc(issueName(k))).join('、'):'标题不足以判断'}（仅标题证据）</td></tr><tr><th>分类线索</th><td>${esc(JSON.stringify(b.situation_evidence))}</td></tr><tr><th>审读工作队列</th><td>${esc(b.review_queue)}</td></tr></table><div class="warn-box"><strong>公开阅读与使用说明</strong><p>下列链接使用你提供的真实 <code>/api/file</code> 下载接口，但此离线原型没有测试服务器上的文件是否存在，也不能把 HTTP 源直接嵌入 HTTPS 网页朗读。下载后可转到电子书工作台读取与试听。未审内容不可直接当作个人辅导处方。</p></div><p><a class="btn primary" href="/TXT/?id=${encodeURIComponent(b.id)}">在本站书籍阅读器打开</a></p><h2>原始 TXT 来源入口</h2><div class="row">${links.join('')}</div><div class="line"></div><p><strong>机器提示：</strong> ${esc(flagsText(b))}</p><button class="btn" data-route="reader">前往本机 TXT 阅读台</button></section>`);}
function renderSelf(){const boxes=[['event','发生了什么？','只记录具体事件、目前是否安全；可不写。'],['facts','我知道的事实与仍未知的','区分看见、本人报告、听说、推断和不知道的。'],['body','身体、环境和关系有哪些限制？','例如睡眠、疾病、工作、胁迫、资源和可用支持。'],['meaning','我给事情怎样解释？有什么替代解释？','这里允许不确定，不要求挖出某个隐藏偶像。'],['scripture','相关经文及其真实上下文','先写段落意义与福音位置；没有把握可以留空。'],['action','一项最小行动、支持与复核','什么我能够做？谁能帮助？何时需要停止和修订？']];container(`<section class="panel">${sectionTitle('个人笔记 · 完全可停止','自我辨析，不是自我诊断','目标不是无限窥探内心，而是分清事实、解释、受苦、责任与支持，选择一项可实行的下一步。全部笔记只保存在当前网页内存，不自动发送网站或保存到浏览器账户。')}<div class="warn-box"><strong>重要边界</strong><p>遇到迫近自伤或他伤危险、持续暴力、明显现实判断异常、严重身体急症或危险戒断，不继续依靠这张表。应根据当地情况立即寻求急救、保护或有资格的专业帮助。网页不计算“风险分数”，也不依据答案宣布你是否有罪或得救。</p></div><div class="grid cols2" style="margin-top:18px">${boxes.map(([id,label,help])=>`<div class="field"><label for="self-${id}">${esc(label)}</label><textarea id="self-${id}" data-note="${id}" placeholder="${esc(help)}">${esc(state.selfNotes[id]||'')}</textarea><small>${esc(help)}</small></div>`).join('')}</div><div class="row" style="margin-top:17px"><button class="btn primary" id="self-download">自愿下载此草稿</button><button class="btn danger" id="self-clear">立即清空草稿</button><button class="btn" data-route="situation">查看专题辨析</button></div><p class="mini-muted">不做自动心理分析、图像上传或数据留存。自愿下载文件后由你本人保管；共享前请删除敏感身份资料。参照专著第44—48章。</p></section>`);}
function renderHelper(){container(`<section class="panel">${sectionTitle('自愿辅导 · 门训 · 纪律须分清','帮助别人，先做忠实的倾听','此页是教会培训框架，不赋予一般志愿者医学、法律或危机处置资格。')}<div class="callout-steps"><div><strong>① 角色与同意</strong><p>说明身份、服务目的、保密及例外。</p></div><div><strong>② 事实与安全</strong><p>先听事情、身体和处境，识别现实保护需要。</p></div><div><strong>③ 经文与智慧</strong><p>按上下文辨明教义，不把假设当启示。</p></div><div><strong>④ 行动与复核</strong><p>共定小步、职责边界、停止与求助条件。</p></div></div><div class="grid cols2" style="margin-top:16px"><div class="card"><h3>双重倾听</h3><p>第一重：当事人发生了什么、如何理解、有什么事实可以纠正当前解释。第二重：圣经在相关上下文中如何说明罪、苦难、恩典、爱、保护和盼望。两重权威不对称，事实不可被宗教口号抹去。</p></div><div class="card"><h3>三轨分离</h3><p>自愿辅导、一般门训和正式纪律相关但不同。纪律必须有正当职分与程序；私人会谈的信息不得未经说明成为控告材料。涉及法律与保护职责须依当地有效程序。</p></div><div class="card"><h3>辅导者的反证</h3><p>每个主要个案假设至少写一条最强替代解释、还缺哪些资料、何种新事实会迫使修订。辅导者不能仅凭症状知道隐藏动机。</p></div><div class="card"><h3>记录、申诉与隐私</h3><p>只收集必要信息、明确访问者与用途；当事人应有质疑、退出、第二意见与投诉渠道。历史资料和正式建议不能混用。</p></div></div><div class="info-box" style="margin-top:18px">研究基线：专著第8—12、31—37、53—56、61—68章。实施时仍须引入当地有资格人员的制度评审。</div></section>`);}
function renderApologetics(){container(`<section class="panel">${sectionTitle('前设护教 · 真理 · 温柔与尊重','护教与辅导：统一而不混同','护教不能成为迫使受辅者接受辅导者判断的逻辑工具；对具体人的解释必须接受事实与反证。')}<div class="grid cols2"><div class="card"><h3>① 明确正在讨论什么</h3><p>是上帝、理性、善恶、历史证据，还是当前真实伤害？先复述对方的具体问题，直到对方认为基本准确。</p></div><div class="card"><h3>② 检查隐藏前提，也检查自己</h3><p>向双方提问：某个判断倚靠哪些终极承诺、事实、经验或个人利益？若观察不符，是否愿意修改推论？</p></div><div class="card"><h3>③ 给出最强合理反方</h3><p>把事实问题、历史作者主张、神学结论和实践技术分开。清楚记录反方最强论证，不用稻草人取胜。</p></div><div class="card"><h3>④ 诚实见证与自由回应</h3><p>在适合的时机陈明三一上帝、基督的位格和工作、悔改信心的呼召。允许提问与不同意，不以辅导服务换取宗教表态。</p></div></div><h2 style="margin-top:20px">三个不会混淆的目标</h2><table class="smalltable"><tr><th>任务</th><th>直接目的</th><th>典型越界</th></tr><tr><td>辅导与牧养</td><td>按真理爱具体的人，分辨问题、行动和支持</td><td>用教义术语代替倾听、保护或医学事实</td></tr><tr><td>护教</td><td>为基督信仰给出理由、回应异议</td><td>逻辑争胜、把不同意见视为反叛</td></tr><tr><td>传福音</td><td>忠实宣告基督与悔改信心</td><td>制造情绪、恐惧或关系依赖来求决定</td></tr></table><div class="warn-box" style="margin-top:16px">危机、受虐和严重身体症状时，应按安全和职责优先处理现实问题，而不是启动抽象世界观辩论。参考专著第58章及其第45—47表。</div></section>`);}
function editorMatches(b){const q=norm(state.editorQ);return !q||[b.original_title,b.source_path,b.research_topic_name,...b.editorial_alerts].some(s=>norm(s).includes(q));}
function renderEditor(){const n=countStats();const rows=books.filter(editorMatches).slice(0,80);if(!rows.length){container(`<section class="panel"><h1>资料审查</h1><div class="field"><label for="editor-q">搜索待审书目</label><input id="editor-q" type="search" value="${esc(state.editorQ)}"></div><p role="status">没有符合当前关键词的书目；没有显示旧书目作为搜索结果。</p><button class="btn" id="editor-clear">清除搜索</button></section>`);return;}const book=rows.find(b=>b.id===state.editorId)||rows[0];state.editorId=book.id;const prop=state.editorNotes[book.id]||{};container(`<section class="panel">${sectionTitle('研究审核台 · 决策与证据分开','机器建议不能取代人工审稿','本地审核演示：可以写调整建议并导出给编辑复核，但不能点击一次就将未经审定的文章发布为专业辅导指导。')}<div class="grid cols4"><div class="stat"><strong>${fmt(n.books)}</strong><small>源路径与 SHA 核对</small></div><div class="stat"><strong>${fmt(n.unknown)}</strong><small>标题处境未识别</small></div><div class="stat"><strong>86</strong><small>重点安全审读队列（非个人风险分级）</small></div><div class="stat"><strong>0</strong><small>正式指导审核批准</small></div></div><div class="editor-w" style="margin-top:17px"><div><div class="field"><label for="editor-q">查找需要人工审读的文件</label><input id="editor-q" value="${esc(state.editorQ)}" placeholder="书名、目录、标记"></div><div class="scroll-list" style="margin-top:10px">${rows.map(b=>`<button data-editbook="${esc(b.id)}" aria-current="${b.id===state.editorId}">${esc(b.original_title)}<small style="display:block">${esc(b.review_queue)}</small></button>`).join('')}</div><small>最多显示前 80 条；搜索或清除关键词以定位。</small></div><div class="card"><h3>${esc(book.original_title)}</h3><span class="pill amber">源文件可核</span><span class="pill amber">内容未终审</span><table class="smalltable"><tr><th>原研究类</th><td>${esc(book.research_topic_name)}</td></tr><tr><th>处境候选</th><td>${book.situations.map(k=>esc(issueName(k))).join('、')||'尚无标题证据'}</td></tr><tr><th>安全与编辑标记</th><td>${esc(flagsText(book))}</td></tr><tr><th>原始路径</th><td style="overflow-wrap:anywhere">${esc(book.source_path)}</td></tr><tr><th>原件校验</th><td>${esc(book.source_sha256)}</td></tr></table><div class="field" style="margin-top:12px"><label for="editor-proposed">建议的研究主类（候选，不是已批准）</label><select id="editor-proposed"><option value="">尚未提出建议</option>${topics.map(t=>`<option value="${t.id}" ${prop.topic===t.id?'selected':''}>${esc(researchTopicLabel(t))}</option>`).join('')}</select></div><div class="field" style="margin-top:12px"><label for="editor-reason">建议依据、原文章节与相反证据</label><textarea id="editor-reason" placeholder="须引用原文位置；事实、解释、教义与建议分开写。">${esc(prop.reason||'')}</textarea></div><div class="row" style="margin-top:14px"><button class="btn primary" id="editor-save">暂存建议（仅本页）</button><button class="btn" id="editor-export">导出当前建议</button></div><p id="editor-status" class="mini-muted" role="status">当前已暂存 ${Object.keys(state.editorNotes).length} 条建议；正式库没有被改写。</p></div></div></section>`);}
function voiceList(){try{return window.speechSynthesis?.getVoices?.()||[]}catch{return []}}
function voiceKey(v){return [v.voiceURI||'',v.name||'',v.lang||''].join('|')}
function hsiao(v){return /HsiaoYu/i.test(v.name||'')||/zh[-_]TW[-_]HsiaoYuNeural/i.test(v.voiceURI||'')}
function voiceName(v){return `${v.name} · ${v.lang} · ${v.localService===false?'浏览器报告联网':'浏览器声音'}`}
function fallbackChinese(){const voices=voiceList();if(window.SpeechVoicePolicy)return window.SpeechVoicePolicy.choose(voices,true).voice;return voices.find(hsiao)||[...voices].filter(v=>/^zh(?:[-_]|$)/i.test(v.lang||'')).sort((a,b)=>{
 const score=v=>(/^zh[-_]tw/i.test(v.lang||'')?0:/^zh[-_]cn/i.test(v.lang||'')?4:8)+(/Microsoft/i.test(v.name||'')?0:/Google/i.test(v.name||'')?1:2);
 return score(a)-score(b)||String(a.name).localeCompare(String(b.name),'zh');})[0]||null;}
function voiceSelectHtml(){const a=voiceList(), auto=fallbackChinese(),selected=state.reader.voiceKey;
 return `<select id="reader-voice"><option value="" ${!selected?'selected':''}>${auto?'自动选择：'+esc(auto.name)+'（'+esc(auto.lang)+'）':'浏览器尚未提供中文声音'}</option>${a.map(v=>`<option value="${esc(voiceKey(v))}" ${selected===voiceKey(v)?'selected':''}>${esc(voiceName(v))}</option>`).join('')}</select><p class="mini-muted">${auto?(hsiao(auto)?'已实际找到小雨命名声音；请试听确认。':'当前浏览器没有小雨，自动使用实际中文声音：'+esc(auto.name)+'（非小雨）。'):'尚无可用中文声音，可尝试刷新或检查系统声库。'}联网发音可能将朗读文本提供给语音服务商。独立云端接口尚未连接。</p>`;}
function paragraphsVisible(){const rr=state.reader;return rr.paras.slice(0,rr.shown).map((txt,i)=>`<div class="read-line" data-readline="${i}" role="button" tabindex="0" aria-current="${rr.current===i}"><small>${i+1}</small><p>${esc(txt)}</p></div>`).join('')||'<p class="hint">请从左侧选择本机 TXT；原文不上传网站。</p>'}
function renderReader(){const rr=state.reader;container(`<section class="paper-grid"><div class="mobile-readbar"><button class="btn primary" id="mobile-controls-toggle" aria-expanded="false" aria-controls="reader-controls-panel">打开阅读控制</button><span>右侧正文 · 点击段落朗读</span></div><div class="reader-backdrop" id="reader-backdrop"></div><aside class="panel paper-controls" id="reader-controls-panel"><button class="btn mobile-close" id="mobile-controls-close">关闭控制面板</button><p class="eyebrow">固定控制面板 · 原文在右侧</p><h2>电子书与朗读</h2><div class="read-controls"><div class="field"><label for="reader-file">打开本机 TXT</label><input id="reader-file" type="file" accept=".txt,text/plain"></div><div class="field"><label for="reader-encoding">文字编码</label><select id="reader-encoding"><option value="auto" ${rr.encoding==='auto'?'selected':''}>自动辨识 UTF-8 / UTF-16 / GB18030</option><option value="utf-8" ${rr.encoding==='utf-8'?'selected':''}>UTF-8</option><option value="gb18030" ${rr.encoding==='gb18030'?'selected':''}>GB18030 / GBK</option><option value="utf-16le" ${rr.encoding==='utf-16le'?'selected':''}>UTF-16 小端</option></select></div><div class="sticky-voice"><strong>声音选择</strong><div class="field" style="margin-top:8px"><label for="reader-voice">目标：微软在线小雨（HsiaoYu）</label>${voiceSelectHtml()}</div><div class="field"><label for="reader-rate">语速 <span id="rate-value">${rr.speed.toFixed(1)}</span></label><input id="reader-rate" type="range" min="0.65" max="1.6" step="0.05" value="${rr.speed}"></div><div class="row"><button class="btn primary" id="tts-play">朗读</button><button class="btn" id="tts-pause">暂停/继续</button><button class="btn" id="tts-stop">停止</button></div><p id="tts-status" role="status" class="mini-muted">${esc(rr.status)}</p></div><div class="field"><label for="reader-find">在已打开的正文里搜索</label><input id="reader-find" placeholder="例如：恩典、盼望" value="${esc(rr.find||'')}"></div><div class="row"><button id="reader-find-btn" class="btn">定位下一个结果</button><button class="btn" id="reader-size-minus">字小</button><button class="btn" id="reader-size-plus">字大</button></div><div class="info-box"><strong>当前文件</strong><p id="reader-title">${esc(rr.title||'无')}</p><small>${fmt(rr.paras.length)} 段；本机导入不向服务器发送内容。</small></div><small>标点保留给语音引擎判断自然语气，不额外插入等待。部分声音可能播出某些符号，网页无法保证所有提供者绝不读出。</small></div></aside><article class="panel paper-view" id="reader-page" style="--readsize:${rr.fontSize||20}px" aria-label="电子书正文"><p class="eyebrow">原文阅读 · 可独立滚动</p><h2>${esc(rr.title||'尚未打开文本')}</h2><div class="warn-box" style="margin-bottom:14px">本机文件不上传本站服务器。朗读优先使用浏览器实际提供的小雨；缺席时自动选择真实中文发音人并标明身份，可能涉及浏览器联网语音服务。此旧互动区主要用于本机文件；网盘正文请进入云端书库。</div>${rr.failed?'<p role="alert">${esc(rr.status)}</p><button class="btn" id="reader-retry">重新读取此文件</button>':''}<div id="reader-lines">${paragraphsVisible()}</div>${rr.paras.length>rr.shown?`<button class="btn" id="reader-more">显示后续正文（已显示 ${rr.shown}／${rr.paras.length} 段）</button>`:''}</article></section>`);if(window.innerWidth<=800){const aside=$('reader-controls-panel');if(aside)aside.inert=!state.mobileControlsOpen;}if(state.mobileControlsOpen)toggleReaderDrawer(true);}
function toggleReaderDrawer(open){state.mobileControlsOpen=open;const aside=$('reader-controls-panel'),back=$('reader-backdrop'),btn=$('mobile-controls-toggle');aside?.classList.toggle('is-open',open);back?.classList.toggle('is-open',open);if(aside&&window.innerWidth<=800)aside.inert=!open;if(btn)btn.setAttribute('aria-expanded',String(open));if(open)document.getElementById('reader-file')?.focus();else btn?.focus();}


/* 第八轮：逐章证据链与教育案例。原著全文未纳入网站；隐私数据不持久化。 */
const EVIDENCE_DATA = {"ledger":[{"id":"D01","title":"罪不再作王与内住之罪并非同一命题","theme":"救赎地位／内住之罪","verses":"罗马书6:6—14；7:21—25；8:13；加拉太书5:16—17","sources":[["B05_罪与恩典的统治.txt","第一章、第二章：约第90—110、154—162行","先申明信徒中有残余之罪，再讨论罪是否具有统治权；作者区分残余力量与最高的主导权。"],["B03_内住之罪.txt","第一章、第二章：约第225—313行","讨论信徒内住之罪的持续作用及其对顺服的抵抗。"]],"claim":"经文中的‘不作王’和‘仍有争战’必须分别解释；不可据一次受试探推断救恩不存在。","inference":"把两书的论证结合为网站两栏：救赎地位与具体行为治理；是否为真信徒不可由软件判定。","action":"针对已经确认的罪行，区分‘已蒙恩的身份’与‘正在学习顺服的责任’，选定一项确实需要停止或修复的行为。","limit":"作者对罗马书7章中‘我’的身份、段落细节需作独立释经；摘录不能当作已完成原文校勘。","status":"原著正文已定点核读；经文中文原译版本、原文释经仍待联合审校"},{"id":"D02","title":"遭遇试探、陷入试探与实际犯罪必须区分","theme":"试探辨析","verses":"马太福音26:41；雅各书1:12—15；希伯来书4:15","sources":[["B04_论试探.txt","第一、二章：约第148—281行","原著将试探与‘进入试探’分别阐述；不仅凭试探出现就判定人已经犯罪。"]],"claim":"试探不是自动等于已犯罪；程序必须先询问实际选择、言语与行为。","inference":"网站提供‘遇到诱惑但没有同意或付诸行动’与‘已经发生实际不义行为’两个不同练习分支。","action":"对未落实的诱惑，转向警醒与预备；对真实发生的罪，进一步核对事实与责任。","limit":"‘进入试探’有内在纠缠的含义，不能用一个选项直接读心；隐秘同意与个人意识需谨慎论证。","status":"已核原著第一、二章相关段落；希伯来书4:15的应用需单独核语境"},{"id":"D03","title":"警醒、祷告和认识试探时机是主动操练","theme":"警醒与预防","verses":"马太福音26:41；哥林多前书10:12—13；彼得前书5:8—9","sources":[["B04_论试探.txt","第五至八章：约第502—842行","重点讨论警醒、祷告、身处不同试探时机时的预备，及对自恃的批判。"]],"claim":"不能只在犯错之后进行反思；基督的命令包括实际的警醒和祷告。","inference":"在‘预防下一次’页面可让用户自愿选择一项避免诱因或提醒祷告的具体安排，但不是圣经指定的唯一操作。","action":"设计一项具体可执行的预防措施，并核对其是否合乎人身安全与正当责任。","limit":"软件不能保证仅凭提醒或记分就能控制一切试探；作者举例亦非普遍诫命。","status":"已核相关章节标题与代表性正文；所有实例未逐项核读"},{"id":"D04","title":"守心包含按经文默想与祷告，不等于强制搜索隐藏罪","theme":"内住之罪与守心","verses":"箴言4:23；诗篇119:11；歌罗西书3:16；马太福音15:18—20","sources":[["B03_内住之罪.txt","第三章、第九章：约第344—367、979—997行","讨论心的地位及借经文默想、祷告认识自身的责任。"],["C02_保守己心.txt","正文开头及‘什么时候应保守己心’各节","从箴言4:23展开在不同处境下保守己心的实践，而非只从心理情绪推定有罪。"]],"claim":"受造的人需要按神的话留心自己的言行与内心，但不得将推测当作确切罪责。","inference":"提供‘经文—具体事实—可更正解释’三栏，禁止由情绪关键词自动产生罪因结论。","action":"自愿记录一句准确经文、一项可核实行动和一条仍未确定的解释。","limit":"原著中的‘心’概念跨越不同经文用法，不得未经释经直接等同现代心理学单一构念。","status":"核心段落已定位；弗拉维尔全文诸处境尚未终审"},{"id":"D05","title":"悔改不是一时恐惧、决心或完成表格","theme":"真实悔改","verses":"使徒行传3:19；哥林多后书7:9—11；以弗所书4:25—32","sources":[["B06_悔改的教义.txt","第二章约第304—336行；第三、四章约第336—693行","先辨别虚假悔改，再用见罪、忧罪、认罪、羞罪、恨罪、转离罪六个要素解释真实悔改。"]],"claim":"单纯因后果害怕或承诺以后不再犯，不足以代替实际转离罪和实行善行。","inference":"六项是作者的系统整理，不应被改造成六项情绪强度评分；程序须用行为和经文关系核查。","action":"若事实确证，具体说明需要停止的言语或行为、需要修正的损害以及应实践的正面义行。","limit":"情绪表达方式与强度因人而异；对有强制或虐待风险者不得强迫面对加害者作不安全的承认。","status":"已核第二至四章；六项主张的各节经文仍应独立复核"},{"id":"D06","title":"律法是蒙恩者生活的规范，却不是称义的功劳条件","theme":"律法、恩典与顺服","verses":"罗马书3:28—31；6:14；以弗所书2:8—10；约翰福音14:15","sources":[["B08_律法的恩典.txt","第六章约第4790—4936、5026—5043行","作者整理清教徒以客观律法指导信徒生活，同时反对把新顺服作为称义功德的争论。"],["B05_罪与恩典的统治.txt","第五章约第453—553行","强调胜过罪统治的力量来自在基督里所赐的恩典，不是律法自身赋能。"]],"claim":"真实顺服有客观圣经规范，不能以‘随感觉’取代诫命；也不能以实际操练换取称义。","inference":"建立两个独立字段：‘经文所要求的道德责任’与‘读者自愿选择的具体执行方式’，不准互相冒名。","action":"从相关经文找出明确禁止和命令，然后选择一项非强制的合宜行动。","limit":"这部书是对清教徒神学的历史研究，并非其引用的每位作者都同意所有用语；保留新律法主义争议。","status":"第六章关键争论已定位并核读；更多清教徒原始引文待对读"},{"id":"D07","title":"行动复核必须问‘是否真实改变’，而非‘是否完成关卡’","theme":"实践验收","verses":"以弗所书4:28—29；雅各书1:22—25；加拉太书6:1","sources":[["B06_悔改的教义.txt","第四章约第640—690行","论转离罪而归向神的实际转变。"],["B08_律法的恩典.txt","第六章约第5020—5043行","强调信徒持续顺服的方向、见证与新生命，而非凭一次行为判断全部属灵状态。"]],"claim":"应用应关注真实停止恶行、必要修复和穿上新人，不以表单次数或游戏成绩断定属灵地位。","inference":"通过‘试探—选择—行动—复核’建立非评分式练习，可选择‘证据不足’或‘暂不做道德判断’而结束。","action":"自愿写下下一次相似情境中的具体替代行为，并在日后用实际事实校正；不上传个人记录。","limit":"福音操练结果包含人的内在和关系因素，网站只能核对可观察事实，不能裁定圣灵工作的全部果效。","status":"已核主题相关段落；用户实际使用验收待完成"}],"training":[{"id":"T1","title":"听见诱惑，却没有采取错误行动","facts":"有人邀请你一起传播未经核实的不实消息；你拒绝了，并决定先查证。","correct":"prevention","feedback":"这不是已经查明的说谎行为。可研究试探、警醒及审慎查证，不强制进入认罪环节。","source":"D02、D03"},{"id":"T2","title":"明知消息虚假，仍故意传播","facts":"一位虚构人物已知某消息不实，却为了让同事受损，主动传播并坚称属实。","correct":"repentance","feedback":"存在已明确的欺骗及伤害事实。可核对出埃及记20:16、以弗所书4:25，再研究认罪、停止传播、纠正受损信息和诚实言语。","source":"D05、D06、D07"},{"id":"T3","title":"记忆错误造成的数字差异","facts":"某人转述一份统计表时把数字记错；尚无证据证明他知情或故意误导。","correct":"unknown","feedback":"可以建议核对并纠正客观信息，但尚不能称为故意说谎。人的推论不得冒充上帝的定罪。","source":"D01、D05"},{"id":"T4","title":"被要求承担未证实的罪责","facts":"辅导者仅凭对方失眠或流泪，就断言其‘必定隐藏着悖逆的偶像’，要求承认；没有具体行为证据。","correct":"boundary","feedback":"应当拒绝以症状和猜测作道德判决，停止强制认罪流程，并在需要时寻求可信的现实支持。","source":"D04、D05"}]};
let evidenceCurrent = 0, evidenceCase = 0, evidenceSelected = '';
function renderEvidence(){
 const d=EVIDENCE_DATA.ledger[evidenceCurrent];
 const c=EVIDENCE_DATA.training[evidenceCase];
 const tabs=EVIDENCE_DATA.ledger.map((x,i)=>`<button type="button" data-evidence-index="${i}" aria-current="${i===evidenceCurrent}">${esc(x.id)}　${esc(x.title)}</button>`).join('');
 const src=d.sources.map(s=>`<div class="evidence-src"><b>${esc(s[0])}</b><small>${esc(s[1])}</small><p>${esc(s[2])}</p></div>`).join('');
 const choices=[['prevention','尚未证实犯罪：警醒与查证'],['repentance','事实已确证：研究具体悔改'],['unknown','证据不足：先核实事实'],['boundary','停止强制定罪并保护']];
 const buttons=choices.map(([v,t])=>`<button type="button" data-evidence-choose="${v}" aria-pressed="${evidenceSelected===v}">${esc(t)}</button>`).join('');
 const selected=evidenceSelected ? `<div class="evidence-result" role="status"><b>${evidenceSelected===c.correct?'此练习的判断与现有材料相符':'需要重新检查事实与责任'}</b><p>${esc(c.feedback)}</p><p class="mini-muted">相关证据链：${esc(c.source)}。这是虚构教学情境，不能自动判定真实人物。</p></div>` : '';
 container(`<section class="panel intro">${sectionTitle('第八轮 · 原文证据 · 可否证的实践规则','从圣经命题到具体操练：双重证据链','本页把经文、作者对经文的解释、现代工作规则分开。不因作者声望给出自动诊断；也不因方法有步骤就否认圣经操练的效用。')}</section>
 <div class="evidence-grid" style="margin-top:16px"><aside class="panel evidence-sidebar"><h2>七项重点论证</h2><p class="mini-muted">共${EVIDENCE_DATA.ledger.length}张核读卡。核读不等于全部原著终审，也不等于原文圣经校勘已完成。</p><div class="evidence-tabs">${tabs}</div><button type="button" class="btn soft" style="margin-top:12px" data-route="corebooks">返回16本书目</button></aside>
 <article class="panel evidence-detail"><p class="eyebrow">${esc(d.id)}　${esc(d.theme)}</p><h2>${esc(d.title)}</h2><p><strong>核对经文：</strong>${esc(d.verses)}</p><h3>一、实际原著的陈述和位置</h3>${src}<h3>二、需要检验的经文命题</h3><p>${esc(d.claim)}</p><div class="evidence-steps"><div><b>第三方作者的理解</b>${esc(d.sources.map(x=>x[2]).join('；'))}</div><div><b>本程序的推论（可推翻）</b>${esc(d.inference)}</div><div><b>具体操练建议（非圣经命令原文）</b>${esc(d.action)}</div></div><div class="evidence-warning"><b>反证与边界</b><p>${esc(d.limit)}</p><small>核验状态：${esc(d.status)}</small></div><div class="row"><button class="btn primary" type="button" data-route="practice">进入现有四步学习</button><button class="btn" type="button" data-route="journey">九阶段辨析</button></div></article></div>
 <section class="panel" style="margin-top:16px"><p class="eyebrow">案例分流训练 · 仅教学演示</p><h2>先判断事实，才决定是不是进入治死罪流程</h2><div class="field"><label for="evidence-case">选择一个虚构情境</label><select id="evidence-case">${EVIDENCE_DATA.training.map((x,i)=>`<option value="${i}" ${i===evidenceCase?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div><p style="margin-top:14px">${esc(c.facts)}</p><div class="evidence-choices">${buttons}</div>${selected}<p class="mini-muted">本地页面不存储练习选择，不以此证明用户重生或定罪，也不把人制定的教学关卡变成蒙恩条件。</p></section>`);
}
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.evidenceIndex!==undefined){evidenceCurrent=Number(b.dataset.evidenceIndex);renderEvidence();return;}
 if(b.dataset.evidenceChoose){evidenceSelected=b.dataset.evidenceChoose;renderEvidence();return;}
});
document.addEventListener('change',e=>{
 if(e.target?.id==='evidence-case'){evidenceCase=Number(e.target.value)||0;evidenceSelected='';renderEvidence();}
});

function renderCoreBooks(){
 const categories=['全部','罪论成圣与伦理','圣经辅导方法','圣灵心与教会实践'];
 const buttons=categories.map(x=>`<button class="btn ${coreCategory===x?'primary':''}" data-corecat="${esc(x)}" aria-pressed="${coreCategory===x}">${esc(x)}（${coreBooks.filter(y=>x==='全部'||y.category===x).length}）</button>`).join('');
 const filtered=coreBooks.filter(x=>coreCategory==='全部'||x.category===coreCategory);
 const rows=filtered.map(b=>`<article class="panel" style="margin:11px 0;padding:20px" aria-label="${esc(b.name)}"><h3 style="margin:0 0 8px">${esc(b.name)}</h3><p style="margin:4px 0 14px"><b>辅导主题：</b>${esc(b.focus)}</p><p>从圣经经文出发，学习真理解释、真实处境判断、可实行的步骤和谨慎的安全界限。</p><p><a class="btn primary" style="display:inline-block;text-decoration:none;padding:10px 16px" href="/counseling/guide/?book=${encodeURIComponent(b.id)}">阅读${b.id==='A01'?'十二课完整':'本主题'}辅导正文</a></p></article>`).join('');
 container(`<section class="panel intro">${sectionTitle('完整的原创中文辅导正文','十六个主题 · 真正可阅读的辅导课程','进入各主题后可以直接阅读经文解释、虚构案例、实际操练、反思问题和参考祷告，而不是内部审查记录。')}</section><div class="side-grid" style="margin-top:16px"><aside class="panel side"><h2>按主题筛选</h2><div class="col">${buttons}</div><div class="line"></div><p><a class="btn primary" href="/counseling/guide/?book=A01" style="display:inline-block;text-decoration:none;padding:10px">从第一课正式开始</a></p><p class="hint">正文为原创教材，不是受版权限制的原著译本。您可以按主题选课，也可直接进入十二课系统课程。</p></aside><section class="content-block">${rows}</section></div>`);
}
document.addEventListener('click',e=>{const b=e.target.closest('button[data-corecat]');if(!b)return;coreCategory=b.dataset.corecat;renderCoreBooks();});

function render(){if(state.route==='home')renderHome();if(state.route==='cases')renderCases();if(state.route==='practice')renderPractice();if(state.route==='sources')renderSources();if(state.route==='corebooks')renderCoreBooks();if(state.route==='evidence')renderEvidence();if(state.route==='journey')renderJourney();if(state.route==='situation')renderSinDirectory();if(state.route==='library')renderLibrary();if(state.route==='self')renderSelf();if(state.route==='helper')renderHelper();if(state.route==='apologetics')renderApologetics();if(state.route==='editor')renderEditor();if(state.route==='reader')renderReader();}
function writeResearchAddress(replace=true){if(state.restoringRoute||location.protocol==='file:')return;const p=new URLSearchParams({view:state.route});
 if(state.route==='library'){for(const [key,value] of [['q',state.libQ],['sit',state.libSit],['topic',state.libTopic],['review',state.libReview],['page',String(state.libPage)]])if(value&&value!=='all'&&value!=='0')p.set(key,value);if(state.book)p.set('book',state.book);}
 const u=new URL(location.href);u.hash=p.toString();if(u.href===location.href)return;try{history[replace?'replaceState':'pushState']({},'',u);}catch{}
}
function cancelReaderLoad(){state.readerLoad++;if(state.readerPending){state.readerPending=false;state.reader.failed=!!state.readerFile;state.reader.status='文件读取已取消，可重新读取。';}}
function restoreResearchAddress(){const p=new URLSearchParams(location.hash.slice(1));if(!p.has('view')){if(!location.hash)navigate('home',{history:false});return;}
 const route=p.get('view');if(!nav.some(x=>x[0]===route))return;state.restoringRoute=true;cancelReaderLoad();stopTTS();
 try{state.route=route;state.book=null;state.libQ=(p.get('q')||'').slice(0,120);state.libSit=['all','none',...sitById.keys()].includes(p.get('sit'))?p.get('sit'):'all';state.libTopic=['all',...topicById.keys()].includes(p.get('topic'))?p.get('topic'):'all';state.libReview=['重点安全审查','优先人工核类','常规语义审读'].includes(p.get('review'))?p.get('review'):'all';const page=Number(p.get('page'));state.libPage=Number.isInteger(page)&&page>=0?page:0;
  render();if(route==='library'&&p.has('book')){if(byId.has(p.get('book')))renderBookDetail(p.get('book'));else container('<section class="panel"><h1>未找到该书目</h1><p>链接中的书目编号不在当前目录。</p><button class="btn" data-route="library">返回书目检索</button></section>');}
  $('view')?.focus({preventScroll:true});
 }finally{state.restoringRoute=false;}
}
function navigate(route,opt={}){if(!nav.some(x=>x[0]===route))return;if(state.route==='editor'&&$('editor-reason'))updateEditor();if(state.route==='reader'&&route!=='reader'){cancelReaderLoad();stopTTS();}state.route=route;state.book=null;if(opt.history!==false)writeResearchAddress(false);render();window.scrollTo({top:0,behavior:'auto'});$('view')?.focus({preventScroll:true});}

function downloadText(name,data,type='text/plain;charset=utf-8'){const blob=new Blob(['\ufeff',data],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),5000);}
function decodeText(bytes,enc){const b=new Uint8Array(bytes);if(enc==='auto'){
 if(b.length>=2&&b[0]===0xff&&b[1]===0xfe)enc='utf-16le';
 else if(b.length>=2&&b[0]===0xfe&&b[1]===0xff)enc='utf-16be';
 else {try{return new TextDecoder('utf-8',{fatal:true}).decode(b).replace(/^\ufeff/,'')}catch{enc='gb18030'}}
 }
 return new TextDecoder(enc,{fatal:true}).decode(b).replace(/^\ufeff/,'');}
function makeParas(t){const normalized=t.replace(/\r\n?/g,'\n').replace(/\u0000/g,'').trim();let blocks=normalized.split(/\n\s*\n/g).map(x=>x.trim()).filter(Boolean);if(blocks.length<4&&normalized.length>1000)blocks=normalized.split(/\n/g).map(x=>x.trim()).filter(Boolean);return blocks.flatMap(x=>x.length>8000?x.match(/[\s\S]{1,6000}/g)||[]:[x]);}
async function openReaderFile(file){if(!file)return;const token=++state.readerLoad;state.readerFile=file;state.readerPending=true;state.reader.failed=false;stopTTS();state.reader.title=file.name;state.reader.bytes=null;state.reader.paras=[];state.reader.current=0;state.reader.shown=120;setReaderStatus('正在读取本机文件……');if(state.route==='reader')renderReader();
 try{if(file.size>20_000_000)throw Error('单份文件超过20兆字节，请先分卷读取；没有截断原文。');const bytes=await file.arrayBuffer();if(token!==state.readerLoad||state.route!=='reader')return;if(bytes.byteLength>20_000_000)throw Error('文件超过20兆字节');state.reader.bytes=bytes;const text=decodeText(bytes,state.reader.encoding);if(!text.trim())throw Error('文本为空');
  state.reader.paras=makeParas(text);state.reader.shown=Math.min(120,state.reader.paras.length);state.reader.current=0;state.reader.status=`已读取 ${fmt(bytes.byteLength)} 字节、${fmt(state.reader.paras.length)} 段；未上传。`;state.reader.failed=false;state.readerPending=false;state.mobileControlsOpen=false;renderReader();
 }catch(error){if(token!==state.readerLoad||state.route!=='reader')return;state.reader.paras=[];state.reader.failed=true;state.readerPending=false;state.reader.status='打开失败：'+error.message;renderReader();}
}
function stopTTS(){state.voiceOpt++;state.playing=false;state.paused=false;state.reader.resumeNext=null;try{window.speechSynthesis?.cancel()}catch{}}
function splitLong(s,max=240){if(window.ReaderSpeechSegments)return window.ReaderSpeechSegments(s,max).map(x=>x.text);if(s.length<=max)return[s];let results=[],remain=s;while(remain.length>max){let end=Math.max(remain.lastIndexOf('。',max),remain.lastIndexOf('？',max),remain.lastIndexOf('！',max),remain.lastIndexOf('；',max));if(end<max*0.45)end=max-1;results.push(remain.slice(0,end+1));remain=remain.slice(end+1);}if(remain)results.push(remain);return results;}
function voiceObject(){const wanted=state.reader.voiceKey;return (wanted?voiceList().find(v=>voiceKey(v)===wanted):null)||fallbackChinese();}
function playTTS(idx){if(state.route!=='reader')return;if(typeof window.SpeechSynthesisUtterance!=='function'||!window.speechSynthesis){setReaderStatus('本浏览器不提供朗读接口；文字阅读不受影响。');return;}if(!state.reader.paras.length){setReaderStatus('没有已打开的正文。');return;}const v=voiceObject();if(!v){setReaderStatus('当前没有浏览器实际提供的中文声音，请检查系统语音或刷新声音列表。');return;}
 stopTTS();const op=state.voiceOpt;const tasks=[];for(let i=idx;i<state.reader.paras.length;i++)for(const t of splitLong(state.reader.paras[i]))tasks.push({i,text:t});let ptr=0;state.playing=true;
 const next=()=>{if(op!==state.voiceOpt||!state.playing)return;if(state.paused){state.reader.resumeNext=next;return;}if(ptr>=tasks.length){state.playing=false;setReaderStatus('朗读完成。');return;}const task=tasks[ptr++];state.reader.current=task.i;const line=document.querySelector(`[data-readline="${task.i}"]`);document.querySelectorAll('[data-readline][aria-current="true"]').forEach(x=>x.setAttribute('aria-current','false'));if(line){line.setAttribute('aria-current','true');line.scrollIntoView({block:'nearest',behavior:'instant'});}
 const utter=new SpeechSynthesisUtterance(task.text);utter.voice=v;utter.lang=v.lang||'zh-TW';utter.rate=state.reader.speed;utter.volume=1;utter.onend=next;utter.onerror=e=>{if(op!==state.voiceOpt)return;state.playing=false;setReaderStatus('当前语音引擎中断：'+(e.error||'未知错误'));};try{window.speechSynthesis.speak(utter);setReaderStatus('正在以 '+v.name+' 朗读；段落 '+(task.i+1)+'／'+state.reader.paras.length);}catch(e){state.playing=false;setReaderStatus('语音调用失败：'+e.message);}};try{window.speechSynthesis.resume();}catch{}next();}
function setReaderStatus(s){state.reader.status=s;if($('tts-status'))$('tts-status').textContent=s;}
function locateText(){const q=norm($('reader-find')?.value);if(!q)return;stopTTS();state.reader.find=q;const start=state.reader.current+1;const idx=state.reader.paras.findIndex((s,i)=>i>=start&&norm(s).includes(q));const found=idx<0?state.reader.paras.findIndex(s=>norm(s).includes(q)):idx;
 if(found<0){stopTTS();document.querySelectorAll('[data-readline][aria-current="true"]').forEach(n=>n.setAttribute('aria-current','false'));setReaderStatus('在此文中未找到该关键词；已停止朗读。');return;}
 state.reader.current=found;if(found>=state.reader.shown){state.reader.shown=found+1;renderReader();}const node=document.querySelector(`[data-readline="${found}"]`);if(node){node.scrollIntoView({block:'center',behavior:'smooth'});node.focus({preventScroll:true});}setReaderStatus('找到第 '+(found+1)+' 段。');}
function updateEditor(){const b=byId.get(state.editorId);if(!b)return;state.editorNotes[b.id]={topic:$('editor-proposed').value,reason:$('editor-reason').value.trim(),sourcePath:b.source_path,sourceSHA256:b.source_sha256,approval:'仅候选，请独立复核'};$('editor-status').textContent='已暂存候选，正式书目未改变。';}

// 第四版：属灵责任辨析旅程（教育性工具，不作医疗/心理诊断，不评定救恩）。
const journeyModules=JSON.parse(document.getElementById('journey-modules').textContent);
const journeyStages=['界限与同意','选定行为主题','具体事实','查验经文','责任与反证','福音与恩典','脱去旧人','穿上新人','复核与结束'];
const journey={stage:0,module:journeyModules[0].id,choice:'',notes:{},outcome:'',finished:false,started:false,feedback:''};
function jmodule(){return journeyModules.find(m=>m.id===journey.module)||journeyModules[0];}
function jinput(k,label,help,rows=3){return `<div class="field"><label for="j-${k}">${esc(label)}</label><textarea id="j-${k}" rows="${rows}" data-journey-note="${esc(k)}" placeholder="${esc(help)}">${esc(journey.notes[k]||'')}</textarea></div>`;}
function jcontext(){const m=jmodule();return `<aside class="journey-context"><span class="pill green">经文讨论需要查验上下文</span><h3>${esc(m.name)}</h3><p>${esc(m.subtitle)}</p><div class="line"></div><p><b>要核实的具体行为：</b>${esc(m.action)}</p><p><b>参考经文：</b>${esc(m.scriptures)}</p><p class="mini-muted">由编辑提出的示范场景，不是个人定罪或自动神学审批。</p></aside>`;}
function jstageContent(){const m=jmodule(),s=journey.stage;
 if(s===0)return `<h2>开始前：确认本工具的边界</h2><p>本旅程只讨论<strong>可具体陈述的思想、言语、选择和行为是否违反圣经的诫命</strong>。不诊断疾病，不根据焦虑、抑郁、受害、疲劳、残疾或不由自主的思想自动判定罪。</p><div class="warn-box"><strong>可随时停止</strong><p>如牵涉即时危险、自伤意念、暴力、受虐或急性身体问题，请退出本训练，优先寻求现实中的紧急与专业支持；无需在本站披露私人细节。</p></div><p class="info-box">游戏机制只用于组织学习，不设置“圣洁等级、罪性分数、上帝悦纳值”。没有完成任务不代表属灵失败。</p><div class="row"><button class="btn primary" data-j-start="1">我了解边界，开始自愿练习</button><button class="btn soft" data-j-stop="1">暂不开始</button></div>`;
 if(s===1)return `<h2>选择一项可以查验的言行</h2><p>先选发生过的行为主题，不要因为一个情绪词就认定“我犯罪了”。</p><div class="journey-topics">${journeyModules.map(x=>`<button data-j-topic="${x.id}" aria-pressed="${journey.module===x.id}"><strong>${esc(x.name)}</strong><small>${esc(x.subtitle)}</small></button>`).join('')}</div>`;
 if(s===2)return `<h2>把事实与解释分开</h2><p>像忠实证人一样描述具体时间、言语与行为。未发生的猜测不是事实。</p>${jinput('event','确实发生了什么？','举一个具体例子，不必填写姓名')}${jinput('people','哪些人直接受到影响？','只记责任相关事实，不记与主题无关的隐私')}${jinput('unknown','哪些细节我仍不知道？','允许存在尚未确定的地方')}`;
 if(s===3)return `<h2>从经文上下文理解责任</h2><div class="card"><strong>${esc(m.scriptures)}</strong><p>${esc(m.law)}</p></div><p>经文的直接诫命、经文原则的合理推论、辅导者的具体建议应分别标明；不得用一节经文越权指定个人生活细节。</p>${jinput('scripture','经文实际明确要求或禁止什么？','写下可核查的经文责任，或保留待核')}${jinput('application','为什么这项具体言行可能涉及此诫命？','先给出支持理由，再查看可能的反证')}`;
 if(s===4)return `<h2>最重要的一关：禁止自动定罪</h2><p><strong>竞争解释：</strong>${esc(m.alternative)}</p>${journey.feedback?`<p class="warn-box">${esc(journey.feedback)}</p>`:''}<div class="row" role="group" aria-label="目前责任证据情况"><button class="btn ${journey.choice==='clear'?'primary':''}" data-j-choice="clear">我能指出明确而自主的具体错误</button><button class="btn ${journey.choice==='uncertain'?'primary':''}" data-j-choice="uncertain">事实仍不清楚</button><button class="btn ${journey.choice==='outside'?'primary':''}" data-j-choice="outside">主要是症状、受害或受限经历</button></div><p class="mini-muted">这是你对资料状态的选择，并非本程序证明你的动机。若不能说明具体行为，本旅程只记录待查，不要求认罪。</p>${jinput('counter','哪一种事实可能推翻我刚才的解释？','例如误解、遭胁迫、不具备能力或需要进一步证人')}`;
 if(s===5)return `<h2>律法与福音不应混同</h2><div class="grid cols2"><div class="card"><h3>律法揭示责任</h3><p>${esc(m.law)}</p></div><div class="card"><h3>福音提供盼望</h3><p>${esc(m.gospel)}</p></div></div><p>罪的赦免与义的地位不能凭本程序的任务完成度购买。生命改变也不是按分数证明救恩。</p>${jinput('grace','关于基督与恩典，我需要重新相信和记住什么？','写经文、祷告方向或目前仍不理解的问题')}`;
 if(s===6)return `<h2>脱去旧人：停止真实的不义</h2><p><strong>针对本题的示范：</strong>${esc(m.putoff)}</p><p>只针对可证实且由本人负责的言行；不得替别人认罪，也不得被迫向施害者接触或泄露安全信息。</p>${jinput('stopact','我愿停止哪一项具体错误？','写一项当下可以停止的行为')}${jinput('repair','是否需要纠正事实、归还或修复损害？','考虑合法、合宜、安全的步骤；也可以写“需咨询可信人士”')}`;
 if(s===7)return `<h2>穿上新人：用合宜的善行替代</h2><p><strong>针对本题的示范：</strong>${esc(m.puton)}</p><p>行动应当<strong>具体、有限、可执行、符合圣经</strong>，不要许下不可能兑现的誓言。</p>${jinput('newact','接下来一个具体行动是什么？','例如明天在交谈前先核对事实，不再传播未经证实的话')}${jinput('support','谁可以在自愿与保密的条件下帮助我？','可以是可信的牧者、同伴，也可选择暂不联系')}${jinput('reviewdate','何时回顾这一行动？','例如本周结束时；不需要每日强迫检查自己所有动机',2)}`;
 if(s===8){const uncertain=journey.choice!=='clear';return `<h2>结束：真实、有限、可以复核</h2><p class="${uncertain?'warn-box':'info-box'}"><strong>${uncertain?'当前结论：证据不足，暂不对自己定罪':'当前记录：你识别了一项需要认真对待的行为责任'}</strong><p>${uncertain?'暂停寻找“隐藏罪根”，可以核实事实、阅读经文或寻求可信帮助。':'这不是“已经完全治愈”或“上帝保证悦纳”的程序证明。继续在福音中依靠恩典，并实行已经明确的合宜行动。'}</p></p><div class="grid cols2"><div class="card"><h3>本次经文</h3>${esc(m.scriptures)}<p>${esc(m.gospel)}</p></div><div class="card"><h3>优先行动</h3><p>${esc(journey.notes.newact||'未选择；允许暂不填写。')}</p><small>复核：${esc(journey.notes.reviewdate||'自行决定')}</small></div></div><div class="row" style="margin-top:18px"><button class="btn primary" data-j-export="1">导出本人记录</button><button class="btn" data-j-reset="1">重新开始一项主题</button><button class="btn soft" data-route="library">查找相关书目研究资料</button></div><p class="mini-muted">自我省察应有结束条件。一个已经清楚处理的事件，不必反复要求自己寻找更深且无法证明的罪。</p>`;}
 return '';
}
function renderSinDirectory(){
 container(`<section class="panel">${sectionTitle('圣经伦理 · 行为责任 · 非疾病诊断','罪责专题学科索引','按十诫与具体言行选择研究主题。标题不能证明一个人的动机；只有有事实依据的言行才可继续属灵责任辨析。')}<p class="warn-box">这里不对焦虑、抑郁、强迫、受伤或失眠等症状进行道德归因，也不进行医疗或心理诊断。</p><div class="grid cols3">${journeyModules.map(m=>`<article class="card"><h3>${esc(m.name)}</h3><p>${esc(m.subtitle)}</p><p class="mini-muted">${esc(m.scriptures)}</p><button class="btn soft" data-j-topic="${m.id}">开始此主题</button></article>`).join('')}</div><p class="mini-muted">十二个主题属于编辑编写的教育性示范，未完成跨教会独立神学审批，不等于1,360篇已终审。</p></section>`);
}
function renderJourney(){const i=journey.stage;
 const nav=journeyStages.map((x,n)=>`<li class="${n===i?'active':''} ${n<i?'done':''}"><span>${n+1}</span>${esc(x)}</li>`).join('');
 container(`<section class="journey-head"><p class="eyebrow">圣经罪责辨析 · 九阶段学习旅程 · 自愿参与</p><h1>以真理察看言行，在恩典中学习悔改</h1><p>专注具体罪行的经文辨析，不是医学诊断，也不宣称可以通过程序彻底治死罪。</p></section><div class="journey-layout"><aside class="panel journey-nav"><h2>旅程进度</h2><ol>${nav}</ol><p class="mini-muted">已查看 ${i+1}／${journeyStages.length} 个阶段；不记录道德积分。</p>${i>0?'<button class="btn soft" data-j-back="1">返回上一步</button>':''}</aside><section class="panel journey-stage" aria-live="polite">${jstageContent()}${i>0&&i<8?`<div class="row journey-next"><button class="btn primary" data-j-next="1">${i===4&&journey.choice!=='clear'?'保留待核并结束':'进入下一阶段'} →</button><button class="btn" data-j-stop="1">停止并清空本次草稿</button></div>`:''}</section>${i>0?jcontext():''}</div>`);
}
function jreport(){return {schema:'personal-spiritual-discernment-v5',status:'本人自愿填写的练习记录；非医疗或神学认证',topic:jmodule().name,scriptures:jmodule().scriptures,choice:journey.choice,conclusion:journey.choice==='clear'?'个人记录：有一项需继续辨析的具体行为责任':'证据不足／不在罪责判定范围；暂不定性',notes:journey.notes,created:new Date().toISOString()};}
// 事件监听只处理本旅程标记，与上一版书目、编辑和阅读器互不覆盖
 document.addEventListener('click',e=>{const x=e.target.closest('button');if(!x)return;
  if(x.hasAttribute('data-j-start')){journey.started=true;journey.stage=1;renderJourney();return;}
  if(x.hasAttribute('data-j-stop')){journey.stage=0;journey.started=false;journey.choice='';journey.notes={};renderJourney();return;}
  if(x.hasAttribute('data-j-topic')){journey.module=x.dataset.jTopic;journey.stage=journey.started?journey.stage:0;state.route='journey';renderJourney();return;}
  if(x.hasAttribute('data-j-choice')){if(x.dataset.jChoice==='clear'&&(!String(journey.notes.event||'').trim()||!String(journey.notes.application||'').trim())){journey.feedback='要暂定具体罪责，至少需要填写已经发生的具体行为和经文的实际应用；若不确定，请选择“事实仍不清楚”。';renderJourney();return;}journey.feedback='';journey.choice=x.dataset.jChoice;renderJourney();return;}
  if(x.hasAttribute('data-j-back')){journey.stage=Math.max(0,journey.stage-1);renderJourney();return;}
  if(x.hasAttribute('data-j-next')){if(journey.stage===4&&journey.choice!=='clear'){journey.stage=8;}else{journey.stage=Math.min(8,journey.stage+1);}renderJourney();return;}
  if(x.hasAttribute('data-j-reset')){journey.stage=0;journey.choice='';journey.notes={};journey.module=journeyModules[0].id;renderJourney();return;}
  if(x.hasAttribute('data-j-export')){downloadText('本人属灵责任辨析_自愿草稿.json',JSON.stringify(jreport(),null,2),'application/json;charset=utf-8');return;}
 });
 document.addEventListener('input',e=>{if(e.target.hasAttribute('data-journey-note'))journey.notes[e.target.dataset.journeyNote]=e.target.value;});

function initEvents(){document.addEventListener('click',e=>{const line=e.target.closest('[data-readline]');if(line&&window.getSelection()?.isCollapsed!==false){playTTS(Number(line.dataset.readline));return;}const el=e.target.closest('button');if(!el)return;
 if(el.id==='reader-retry'){openReaderFile(state.readerFile);return;}if(el.id==='editor-clear'){state.editorQ='';renderEditor();$('editor-q')?.focus();return;}
 if(el.id==='mobile-controls-toggle'){toggleReaderDrawer(true);return;}
 if(el.id==='mobile-controls-close'){toggleReaderDrawer(false);return;}
 if(el.dataset.route){navigate(el.dataset.route);return;}
 if(el.dataset.example){state.example=el.dataset.example;renderSituation();return;}
 if(el.dataset.searchSit){state.libSit=el.dataset.searchSit;state.libPage=0;navigate('library');return;}
 if(el.dataset.book){renderBookDetail(el.dataset.book);$('view')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'auto'});return;}
 if(el.dataset.page){state.libPage=Math.max(0,state.libPage+(el.dataset.page==='next'?1:-1));writeResearchAddress(false);renderLibrary();$('view')?.focus({preventScroll:true});return;}
 if(el.dataset.editbook){state.editorId=el.dataset.editbook;renderEditor();return;}
 if(el.dataset.readline!==undefined){playTTS(Number(el.dataset.readline));return;}
 if(el.id==='lib-clear'){state.libQ='';state.libSit='all';state.libTopic='all';state.libReview='all';state.libPage=0;renderLibrary();return;}
 if(el.id==='self-clear'){state.selfNotes={};renderSelf();return;}
 if(el.id==='self-download'){const data=['自我辨析草稿','只供本人使用，不是个案诊断或公开辅导指导','',...Object.entries(state.selfNotes).map(([k,v])=>`${k}\n${v}`)].join('\n\n');downloadText('我的自我辨析草稿.txt',data);return;}
 if(el.id==='editor-save'){updateEditor();return;}
 if(el.id==='editor-export'){if($('editor-reason'))updateEditor();downloadText('第三轮分类建议_待总核.json',JSON.stringify({schema:'candidate-v1',timestamp:new Date().toISOString(),notes:state.editorNotes},null,2),'application/json;charset=utf-8');return;}
 if(el.id==='tts-play'){playTTS(state.reader.current);return;}
 if(el.id==='tts-stop'){stopTTS();setReaderStatus('已停止。');return;}
 if(el.id==='tts-pause'){try{const sy=window.speechSynthesis;if(!state.playing){setReaderStatus('尚未播放。');return;}if(sy.paused){sy.resume();state.paused=false;const pending=state.reader.resumeNext;state.reader.resumeNext=null;pending?.();setReaderStatus('继续朗读。')}else{sy.pause();state.paused=true;setReaderStatus('已暂停。')}}catch(err){setReaderStatus('暂停功能不可用：'+err.message)}return;}
 if(el.id==='reader-more'){const old=state.reader.shown;state.reader.shown=Math.min(state.reader.paras.length,old+120);const area=$('reader-lines');area.insertAdjacentHTML('beforeend',state.reader.paras.slice(old,state.reader.shown).map((txt,i)=>`<div class="read-line" data-readline="${old+i}" role="button" tabindex="0" aria-current="false"><small>${old+i+1}</small><p>${esc(txt)}</p></div>`).join(''));if(state.reader.shown>=state.reader.paras.length)el.remove();else el.textContent=`显示后续正文（已显示 ${state.reader.shown}／${state.reader.paras.length} 段）`;return;}
 if(el.id==='reader-size-plus'||el.id==='reader-size-minus'){state.reader.fontSize=Math.max(16,Math.min(30,(state.reader.fontSize||20)+(el.id.endsWith('plus')?2:-2)));$('reader-page').style.setProperty('--readsize',state.reader.fontSize+'px');return;}
 if(el.id==='reader-find-btn'){locateText();return;}
 });
 document.addEventListener('input',e=>{const el=e.target;
 if(el.dataset.note){state.selfNotes[el.dataset.note]=el.value;return;}
 if(el.id==='lib-q'){if(e.isComposing)return;state.libQ=el.value;state.libPage=0;const selection=el.selectionStart;renderLibrary();const n=$('lib-q');if(n){n.focus();try{n.setSelectionRange(selection,selection)}catch{}}return;}
 if(el.id==='editor-q'){if(e.isComposing)return;if($('editor-reason'))updateEditor();state.editorQ=el.value;const cursor=el.selectionStart;renderEditor();const n=$('editor-q');if(n){n.focus();try{n.setSelectionRange(cursor,cursor)}catch{}}return;}
 if(el.id==='reader-rate'){state.reader.speed=Number(el.value);$('rate-value').textContent=state.reader.speed.toFixed(1);return;}
 });
 document.addEventListener('compositionend',e=>{if(['lib-q','editor-q'].includes(e.target.id))e.target.dispatchEvent(new Event('input',{bubbles:true}));});
 document.addEventListener('change',e=>{const el=e.target;
 if(el.id==='lib-sit'){state.libSit=el.value;state.libPage=0;renderLibrary();$('lib-sit')?.focus({preventScroll:true});return;}
 if(el.id==='lib-topic'){state.libTopic=el.value;state.libPage=0;renderLibrary();$('lib-topic')?.focus({preventScroll:true});return;}
 if(el.id==='lib-review'){state.libReview=el.value;state.libPage=0;renderLibrary();$('lib-review')?.focus({preventScroll:true});return;}
 if(el.id==='reader-encoding'){state.reader.encoding=el.value;if(state.reader.bytes&&state.reader.title){stopTTS();state.reader.paras=[];state.reader.current=0;try{const txt=decodeText(state.reader.bytes,el.value);if(!txt.trim())throw Error('文本为空');state.reader.paras=makeParas(txt);state.reader.shown=Math.min(120,state.reader.paras.length);state.reader.failed=false;state.reader.status='已按所选编码重新读取正文。';}catch(err){state.reader.failed=true;state.reader.status='该编码解码失败，请选择另一编码：'+err.message;}renderReader();}return;}
 if(el.id==='reader-file'&&el.files?.length){openReaderFile(el.files[0]).catch(err=>setReaderStatus('打开失败：'+err.message));return;}
 if(el.id==='reader-voice'){stopTTS();state.reader.voiceKey=el.value;setReaderStatus(el.value?'已明确手选浏览器报告的声音；请试听确认。':'恢复自动优先小雨；缺席时选用并标明真实中文声音。');return;}
 });
 document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.mobileControlsOpen){toggleReaderDrawer(false);return;}if((e.key==='Enter'||e.key===' ')&&e.target.matches('[data-readline]')){e.preventDefault();playTTS(Number(e.target.dataset.readline));}});
 document.addEventListener('click',e=>{if(e.target?.id==='reader-backdrop'&&state.mobileControlsOpen)toggleReaderDrawer(false);});
 if(window.speechSynthesis){window.speechSynthesis.addEventListener?.('voiceschanged',()=>{if(state.route==='reader'&&!state.playing){const cur=state.reader.voiceKey;if(cur&&!voiceList().some(v=>voiceKey(v)===cur)){state.reader.voiceKey='';state.reader.status='先前手选的声音已不可用，已恢复自动中文声音选择。'}renderReader();}})}
 window.addEventListener('pagehide',()=>{cancelReaderLoad();stopTTS();});window.addEventListener('popstate',restoreResearchAddress);window.addEventListener('hashchange',restoreResearchAddress);
}

// 第五轮：原著依据与来源作者的推论分层，不将教材个案判为人的灵性诊断。
const studyCases=[{"id":"C01","title":"明知为假，仍散布指控","situation":"某人明确知道一条针对同事的消息不真实，却继续当作事实传播。","answer":"direct","reason":"题设已有明确的知情、行为与对象，属于可按第九诫及以弗所书4:25辨析的具体不义言行。仍不能从一次行为推定所有隐藏动机。","basis":"出埃及记20:16；以弗所书4:25","source":"亚当斯：第27页区分诫命与具体执行建议"},{"id":"C02","title":"听到消息但不知真假","situation":"某人转发了消息，之后得知可能不实；目前不知道他当时是否故意或已尽核查责任。","answer":"unknown","reason":"可能涉及不负责任的传播，但既不能直接推定故意欺骗，也不能以“我不知道”自动免除一切责任；需要事实核查。","basis":"箴言18:13；雅各书3章","source":"事实未决不等于罪已确立"},{"id":"C03","title":"失去亲人的哀伤","situation":"一名信徒因亲人离世而悲伤流泪，偶尔失眠；没有证据显示其故意伤人或违背明确命令。","answer":"notproof","reason":"悲伤本身不能证明不信、偶像或叛逆。基督也曾哭泣，诗篇有哀歌；本项目不从症状作属灵罪因诊断。","basis":"约翰福音11章；诗篇42篇","source":"亚当斯：第214、429页个人受苦与本罪的区别"},{"id":"C04","title":"正在遭受威胁与暴力","situation":"有人报告持续威胁和暴力，并担心公开求助将遭报复。","answer":"outside","reason":"优先现实安全与适当保护，不运行强迫认罪、夫妻当面对质或催促复合；不要将施害者的责任平均转移给受害者。","basis":"诗篇82篇；相关地区现实保护机制","source":"罪责研究的边界，不做危机或法律诊断"},{"id":"C05","title":"拒绝回答私事","situation":"有人不愿向普通朋友透露个人医疗和财务信息，没有作出虚假陈述。","answer":"notproof","reason":"保护适当隐私或拒绝不合宜要求，本身不是说谎。不可用“隐瞒”这个词直接推出第九诫犯罪。","basis":"出埃及记20:16的实际规范与应用范围","source":"亚当斯：第27页分清命令与人的扩张应用"},{"id":"C06","title":"擅自挪用委托款项","situation":"某人承认明知资金属于公共项目，却将其挪作个人用途并故意掩饰。","answer":"direct","reason":"有主动占有与不诚实陈述的具体事实，涉及第八、九诫。行动建议如退款步骤须遵守现实法律与安全，不能只靠网页一键确定。","basis":"出埃及记20:15–16；以弗所书4:28","source":"原著：诫命明确，具体执行要因情境调整"},{"id":"C07","title":"连续失眠、头痛与乏力","situation":"有人连续数周失眠头痛、力不从心，未报告具体违法或违背圣经的行为。","answer":"notproof","reason":"身体状况不是罪证。网页不做疾病鉴别，也不能以“懒惰、灵性冷淡”替代专业评估。","basis":"约翰福音9:1–3；诗篇的哀诉","source":"亚当斯：第214页拒绝将每人的痛苦与个人罪直接绑定"},{"id":"C08","title":"愤怒但未说明行动","situation":"有人说自己对严重不公很愤怒，却没有说明言语、选择或实际行为。","answer":"unknown","reason":"需分清面对不义的情绪、内心可能的罪性反应及具体伤害。不能把所有愤怒一概定为恶意报复。","basis":"以弗所书4:26–32；雅各书1:19–20","source":"经文要结合上下文与责任事实"},{"id":"C09","title":"存在两个正当选择","situation":"信徒认真考虑两份合法工作，两者均未发现违背明确圣经原则之处。","answer":"notproof","reason":"不能把未选择其中一个说成违背“神唯一私下告诉你的旨意”。当可接受的选项不止一个时，人的谨慎选择有空间。","basis":"罗马书14章；智慧与职业责任","source":"亚当斯：第42—44页讨论多个合乎圣经的选择"},{"id":"C10","title":"因罪被要求危险地和解","situation":"一名受虐者被要求先向施害者道歉，然后立即回去同住，否则便是不顺服。","answer":"outside","reason":"这是可能造成伤害的越权应用；辅导不能用抽象的饶恕命令否认真实危险、权力差异或保护责任。","basis":"公义、保护与真实的责任区分","source":"与原著命令／建议分层原则和现实保护责任核对"},{"id":"C11","title":"对无意念头反复担忧","situation":"有人反复出现不愿意的冒犯性念头，因害怕犯罪而不停向自己追问动机。","answer":"notproof","reason":"不由自主出现的念头，不应仅凭发生就当作主动认同或有意选择；本网站不提供临床诊断，应允许停止过度自省。","basis":"罪责判断必须分清意图、认可与行为","source":"不能以旧目录题名触发定性"},{"id":"C12","title":"主动承认辱骂与修复","situation":"某人承认在争执中故意辱骂家人，想停止伤害并学习诚实、尊重的言语。","answer":"direct","reason":"可以辨析已知的有意伤人行为。停止辱骂可依据经文；具体修复方式需要考虑受害者意愿、安全、适当时机与真实可行性。","basis":"以弗所书4:29–32；箴言15:1","source":"亚当斯：第27页区分原则与行动细节"}];
const studySources=[{"id":"A01","label":"原著已核：个人痛苦不等于本人犯罪","source":"亚当斯：《远超救赎》","location":"中文版第214页；PDF第236页；另见第18章第429页","fact":"作者否认“每个受辅者的问题都直接来自其个人犯罪”的指控，并举约伯与生来瞎眼者作例证。","rule":"个人的疾病、哀伤、受害、情绪或能力限制，不得单独成为个人罪责的判定条件。","level":"原著明确陈述","review":"与本项目核心边界一致"},{"id":"A02","label":"原著已核：上帝命令与人的建议要分开","source":"亚当斯：《远超救赎》","location":"中文版第26—28页；PDF第48—50页（表在第49页）","fact":"作者把圣经直接规定的禁令，与辅导者提出的具体执行步骤、阅读书卷的建议分开。","rule":"显示“直接诫命／可论证原则／具体应用建议／尚属推测”四个层级，后两种不得写成“神命令你如此做”。","level":"原著明确陈述","review":"应纳入所有训练关卡"},{"id":"A03","label":"原著已核：经文要有体系与上下文","source":"亚当斯：《远超救赎》","location":"中文版第15—18页；PDF第37—40页","fact":"作者举祷告经文的误用说明：不能抽离条件，靠孤立节句向人保证想要的结果。","rule":"每一张经文卡必须有经文定位、体裁和上下文提示，鼓励核查相邻经文，不能将应许包装成机械成果。","level":"原著明确陈述","review":"尚需逐题经文终审"},{"id":"A04","label":"原著已核：神学著作本身也承认有待完善","source":"亚当斯：《远超救赎》","location":"中文版前言第xi—xii页；PDF第12—13页","fact":"作者明确承认此书仍有未完成的研究工作，出版是为了推动继续查验与讨论。","rule":"即使是权威原著，网站的“来自原著”也不等于“全部论证已获独立学术确认”。","level":"原著明确陈述","review":"资料状态应可复核"},{"id":"A05","label":"公开许可不能由“免费”推成“人人可再发布”","source":"亚当斯：《远超救赎》中文版","location":"版权页PDF第3页","fact":"中文版声明“仅供美国改革宗翻译社会员使用”与“免费分发，不得出售”，原著版权仍受限制。","rule":"可内部研读、建立书目与有限引证；未经权利人同意，不复制本书整部PDF到公开网站或销售系统。","level":"原书版权条件","review":"公开转载必须另核授权"},{"id":"G01","label":"整合稿已核：其后段区分罪、受害与普遍苦难","source":"《福音之战》","location":"PDF约第492页：罪与苦难；第982页附近：苦难原因讨论","fact":"这份整合稿在后段承认个人罪、他人造成的伤害、疾病与灾难可能在不同个案中发挥不同作用。","rule":"保留该区别；不可用“受苦=本人隐藏罪”覆盖作者后段自己提出的差异。","level":"来源作者的综合论述","review":"并非该书所有章节都前后一致"},{"id":"G02","label":"整合稿已核：护教需要温柔与承认不知道","source":"《福音之战》","location":"PDF约第26—27页；第982页附近","fact":"书中同时强调温柔倾听，并指出人的理性无法得知上帝在某件苦难中的全部特别旨意。","rule":"面向受苦者的程序必须允许“我目前不知道”，不能强迫解释每一场损失的秘密目的。","level":"来源作者的综合论述","review":"与某些战争化修辞存在张力"},{"id":"K01","label":"历史稿待修：对每个忧虑预先定性","source":"《K【自我辅导】亚当斯辅导学派核心理论》","location":"第1章1.1节、第2章2.3节、第3章相关段落","fact":"历史稿存在把每一次忧虑、愤怒、痛苦、受害陈述都直接归结为背叛、偶像或虚假叙事的概括。","rule":"封存为历史研究材料；不允许用这种普遍断言触发程序自动认罪。","level":"编辑批判：待修","review":"与亚当斯明确区分本人罪与苦难的原著相冲突"},{"id":"K02","label":"历史稿待修：用强迫审问代替自愿辨析","source":"《K【自我辅导】亚当斯辅导学派核心理论》","location":"第1章1.4节、第3章3.2节、第4章4.3节","fact":"历史稿多处要求压倒本人的叙事、强行认定内心隐藏动机，甚至用流泪或生理反应作偶像证据。","rule":"不得将这些做法设置成自动引导；先记录事实，允许不确定、拒答、退出、请求陪伴和现实保护。","level":"编辑批判：待修","review":"与温柔、证据和知情同意原则发生冲突"}];
studySources.push(...[{"id":"O01","label":"欧文原著：福音地位先于治死罪的操练","source":"约翰·欧文《论信徒治死罪》","location":"本批PDF第5—9页；第1章《罗马书8:13的根据》","fact":"作者以罗马书8:13为根据，把治死罪的责任明确放在已在基督里、蒙恩的信徒身上；属灵操练不是赚取称义的原因。","rule":"先呈现基督与恩典，再进入悔改操练；不得采用以行为关卡换取“得救确认”的积分机制。","level":"原著明确陈述","review":"已核查指定章节；其他章尚待连续审读"},{"id":"O02","label":"欧文原著：治死罪的施行者是圣灵","source":"约翰·欧文《论信徒治死罪》","location":"本批PDF第18—21页；第3章《圣灵是此工作的唯一施行者》","fact":"作者反对依赖人自创苦修、表面行为和自义来完成治死罪，强调圣灵的工作与信心、蒙恩之道。","rule":"程序只能提供教育、查经、祷告和具体行动提示，不能承诺自动改变心灵，也不能把更多练习误说成更多恩典。","level":"原著明确陈述","review":"对照前言、第一、三章"},{"id":"A06","label":"亚当斯原著：四步教训、督责、归正、学义","source":"杰伊·亚当斯《如何帮助人改变》","location":"本批EPUB目录，第2章、第6—24章；《提摩太后书》3:16的四项功用","fact":"该书以教训、督责、归正、教导人学义为四个核心教学环节，并分别讨论经文原则、罪责证据、悔改及新习惯。","rule":"建立四步教育型模拟训练；在“督责”之前增设事实核实门槛，若罪责不明必须允许不定性、停止或转介。","level":"原著架构（根据实际目录及相关篇章）","review":"已核对目录、引言与相关段落；未声称逐章终审"},{"id":"A07","label":"亚当斯原著：不是人人都辅导所有问题","source":"杰伊·亚当斯《准备好挽回》","location":"本批PDF第12—15页；第1章","fact":"作者区分一般信徒的日常互助与教会正式牧养责任，明确个人并不需要在任何时候处理每一种个案。","rule":"训练者不得冒充牧师、监督者或医疗人员；程序只作教育，遇到危险、复杂权力关系应退出自动流程。","level":"原著明确陈述","review":"已核第1章相关页"},{"id":"A08","label":"亚当斯原著：任何人的具体建议都可质疑","source":"杰伊·亚当斯《基督教辅导者手册》","location":"本批PDF（1110页版本）第22—24页；第3章论辅导权柄","fact":"作者反复区分圣经明文原则与辅导者根据原则提出的执行细节，并指出后者可能错，需要接受受辅者的检验。","rule":"每个工作建议提供“可检验／非圣经明文命令”说明，避免程序把固定时间、动作、表单规定包装为神圣律法。","level":"原著明确陈述","review":"该书多个版本页码不完全一致，定位以1110页版本为准"},{"id":"P01","label":"鲍力生：成圣并非一个固定公式","source":"大卫·鲍力生《成圣如何发生》","location":"本批2017 EPUB：text/part0010.html 附近相关论述","fact":"作者明确反对把对人的帮助简化为一种标准答案；同一真理在不同处境、时段和人身上，需要因人施教。","rule":"四步只作为结构化学习工具，不声称它是唯一的成圣路线；个案细节必须让位于圣经、事实和人与人之间有智慧的关怀。","level":"原著明确陈述","review":"已核指定段落；不同EPUB版式仍待逐项对照"},{"id":"P02","label":"鲍力生：以神的眼光看真实的人","source":"大卫·鲍力生《新眼新见》中文版","location":"本批扫描PDF第14—18、28—31页；含方法、组织与读经视野的前言","fact":"前言讨论概念、方法、教会组织与护教的相互关联，并强调经文和真实生活中的人不能被单一抽象模型取代。","rule":"把抽象罪性分类与真实处境阅读分别建立入口；避免以关键词代替逐人理解。","level":"选页视觉核读（非全文审校）","review":"扫描PDF没有可直接提取的正文；当前只核读指定图像页"},{"id":"R01","label":"波尔顿博士论文：亚当斯与范泰尔既相承也有分歧","source":"贾里德·斯科特·波尔顿《改革辅导》博士论文（2024）","location":"本批PDF第14—16页；第4—6章另展开三方面比较","fact":"论文作者认为亚当斯把圣约知识、前设分析及对立原则带入辅导，却未完整保留范泰尔对普遍恩典、上帝形像等处的若干限定。","rule":"以“某研究者的批判结论”标注，不能宣传亚当斯的任何单一说法都是范泰尔无争议的原意；对分歧需读双方原著。","level":"现代研究者的论证（可争论）","review":"已核摘要、目录及研究方法；未完成全文独立裁决"},{"id":"L01","label":"运动史：亚当斯之后的方法确有发展","source":"希思·兰伯特《亚当斯之后的圣经辅导运动》","location":"本批PDF第10、11—17页；第2—6章目录；版权页第7页","fact":"该书按历史、理论和实际操作变化组织研究，前言由鲍力生撰写，并主张辅导知识要在实践与受监督学习中不断进步。","rule":"网站保留版本、纠错、反证与撤回机制；不以历史先驱或现代机构名义免除独立审校。","level":"作者与前言者观点（研究资料）","review":"已核目录及部分前言；未完成逐页终审"},{"id":"N01","label":"版本事实：2011文件名不能代表出版年份","source":"《亚当斯之后的圣经辅导运动》PDF","location":"本批PDF第7页版权记录","fact":"本批PDF写有版权所有2012、初次印行2012；上传的一个EPUB文件名写2011，不能用文件名覆盖版权页。","rule":"书目年份同时保留“上传文件命名年份”与“原书版次年份”，待核时分别标注。","level":"文献身份实核","review":"已核对版权页"}]);
