// 本页所有训练选择只在内存中；不产生自动发布或用户档案。
document.addEventListener('click',e=>{
 const b=e.target.closest('button');if(!b)return;
 if(b.dataset.studyAnswer){study.answers[studyCases[study.index].id]=b.dataset.studyAnswer;renderCases();return;}
 if(b.dataset.studyIndex!==undefined){study.index=Number(b.dataset.studyIndex);renderCases();return;}
 if(b.id==='study-next'){study.index=Math.min(study.index+1,studyCases.length-1);renderCases();return;}
 if(b.id==='study-prev'){study.index=Math.max(study.index-1,0);renderCases();return;}
 if(b.id==='study-reset'){study.index=0;study.answers={};renderCases();return;}
 if(b.dataset.sourceId){study.currentSource=b.dataset.sourceId;renderSources();return;}
});


